-- Rukwaro Autospares — product catalog seed (31 products)
-- Run AFTER schema.sql in the Supabase SQL Editor.

on conflict (id) do update set
  name = excluded.name,
  price_kes = excluded.price_kes,
  original_price_kes = excluded.original_price_kes,
  image = excluded.image,
  stock_kirinyaga = excluded.stock_kirinyaga,
  stock_industrial = excluded.stock_industrial,
  stock_westlands = excluded.stock_westlands,
  active = excluded.active;
